import { describe, it, expect, vi, beforeEach } from 'vitest';

// search.js reads `document.getElementById('search-bar')` at module load time,
// so the DOM stub has to exist before the module (and this test file's
// imports) are evaluated. vi.hoisted runs before all imports for exactly
// this reason.
vi.hoisted(() => {
	globalThis.__searchBarStub = { value: '' };
	globalThis.document = {
		getElementById: vi.fn(id => (id === 'search-bar' ? globalThis.__searchBarStub : null)),
		getElementsByName: vi.fn(() => []),
	};
});

vi.mock('./fetch.js', () => ({
	fetchExact: vi.fn(),
	fetchFuzzy: vi.fn(),
	fetchFromImdbId: vi.fn(),
	toMovieArray: vi.fn((type, data) => (type === 'exact' ? [data] : data.Search)),
}));

vi.mock('./helpers.js', () => ({
	resetAll: vi.fn(),
	getSpaceSaver: vi.fn(),
	toggleMainSection: vi.fn(),
}));

vi.mock('./watchlist.js', () => ({
	onWatchlist: vi.fn(() => false),
	watchlistArray: [],
}));

vi.mock('./render.js', () => ({
	generateExactResultHtml: vi.fn(),
	generateFuzzyResultsHtml: vi.fn(),
	generateMoreDetails: vi.fn(),
	generateMoreDetailsError: vi.fn(),
}));

import { fetchExact, fetchFuzzy, fetchFromImdbId } from './fetch.js';
import { resetAll, getSpaceSaver } from './helpers.js';
import { generateExactResultHtml, generateFuzzyResultsHtml, generateMoreDetails, generateMoreDetailsError } from './render.js';
import { searchMovies, setSearchType, handleImageError, handleMoreDetailsClick, handleLessDetailsClick } from './search.js';

function createSearchTypeRadios(checkedId) {
	return ['exact-radio', 'fuzzy-radio', 'watchlist-radio'].map(id => ({ id, checked: id === checkedId }));
}

beforeEach(() => {
	vi.clearAllMocks();
	globalThis.__searchBarStub.value = 'Say Anything';
	globalThis.document.getElementsByName = vi.fn(() => createSearchTypeRadios('exact-radio'));
});

describe('setSearchType', () => {
	it('updates the module-level searchType value read by the rest of search.js', async () => {
		const search = await import('./search.js');

		search.setSearchType('exact');
		expect(search.searchType).toBe('exact');

		search.setSearchType('fuzzy');
		expect(search.searchType).toBe('fuzzy');
	});
});

describe('searchMovies', () => {
	it('runs an exact search, normalizes the result, and renders it for a normal query', async () => {
		globalThis.document.getElementsByName = vi.fn(() => createSearchTypeRadios('exact-radio'));
		fetchExact.mockResolvedValue({
			Response: 'True',
			Title: 'Say Anything',
			imdbID: 'tt0098258',
			Ratings: [],
		});

		await searchMovies();

		expect(fetchExact).toHaveBeenCalledWith('Say+Anything');
		expect(resetAll).toHaveBeenCalled();
		expect(generateExactResultHtml).toHaveBeenCalledTimes(1);
		const renderedMovies = generateExactResultHtml.mock.calls[0][0];
		expect(renderedMovies[0].title).toBe('Say Anything');
	});

	it('runs a fuzzy search and renders every normalized result for a normal query', async () => {
		globalThis.document.getElementsByName = vi.fn(() => createSearchTypeRadios('fuzzy-radio'));
		fetchFuzzy.mockResolvedValue({
			Response: 'True',
			Search: [
				{ Title: 'Say Anything', imdbID: 'tt0098258' },
				{ Title: 'Say Anything Else', imdbID: 'tt0000001' },
			],
		});

		await searchMovies();

		expect(fetchFuzzy).toHaveBeenCalled();
		const renderedMovies = generateFuzzyResultsHtml.mock.calls[0][0];
		expect(renderedMovies).toHaveLength(2);
		expect(renderedMovies[1].title).toBe('Say Anything Else');
	});

	it('shows the no-matches empty state instead of rendering when the API finds nothing', async () => {
		globalThis.document.getElementsByName = vi.fn(() => createSearchTypeRadios('exact-radio'));
		fetchExact.mockResolvedValue({ Response: 'False', Error: 'Movie not found!' });
		const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

		await searchMovies();

		expect(getSpaceSaver).toHaveBeenCalledWith('no_matches');
		expect(generateExactResultHtml).not.toHaveBeenCalled();
		consoleSpy.mockRestore();
	});

	it('throws instead of silently rendering when the underlying fetch fails (fetch.js swallows the network error and resolves undefined)', async () => {
		globalThis.document.getElementsByName = vi.fn(() => createSearchTypeRadios('exact-radio'));
		fetchExact.mockResolvedValue(undefined);

		await expect(searchMovies()).rejects.toThrow();
		expect(generateExactResultHtml).not.toHaveBeenCalled();
	});
});

describe('handleImageError', () => {
	it('replaces a broken poster image with the fallback icon and alt text', () => {
		const brokenImage = { src: 'https://broken-url/poster.jpg', alt: 'poster for Say Anything' };

		handleImageError(brokenImage);

		expect(brokenImage.src).toBe('./assets/images/film_icon.png');
		expect(brokenImage.alt).toBe('film poster not found');
	});

	it('overwrites empty/invalid existing src and alt values the same way', () => {
		const brokenImage = { src: '', alt: '' };

		handleImageError(brokenImage);

		expect(brokenImage.src).toBe('./assets/images/film_icon.png');
		expect(brokenImage.alt).toBe('film poster not found');
	});
});

describe('handleMoreDetailsClick', () => {
	function createFakeSummary(imdbID) {
		return {
			attributes: [{}, { value: imdbID }],
			classList: { contains: vi.fn(() => false) },
		};
	}

	it('fetches full details by imdbID and renders them for a normal lookup', async () => {
		const summary = createFakeSummary('tt0098258');
		fetchFromImdbId.mockResolvedValue({
			Response: 'True',
			Title: 'Say Anything',
			imdbID: 'tt0098258',
			Genre: 'Comedy, Drama, Romance',
		});

		await handleMoreDetailsClick(summary);

		expect(fetchFromImdbId).toHaveBeenCalledWith('tt0098258', summary);
		const [, movieDetailsArg] = generateMoreDetails.mock.calls[0];
		expect(movieDetailsArg.title).toBe('Say Anything');
		expect(movieDetailsArg.genre).toBe('Comedy, Drama, Romance');
	});

	it('shows a no-details error when the imdbID has no match in the API', async () => {
		const summary = createFakeSummary('tt0000000');
		fetchFromImdbId.mockResolvedValue({ Response: 'False', Error: 'Incorrect IMDb ID.' });
		const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});

		await handleMoreDetailsClick(summary);

		expect(generateMoreDetailsError).toHaveBeenCalledWith(summary);
		consoleSpy.mockRestore();
	});

	it('throws instead of silently rendering when the underlying fetch fails (fetch.js swallows the network error and resolves undefined)', async () => {
		const summary = createFakeSummary('tt0098258');
		fetchFromImdbId.mockResolvedValue(undefined);

		await expect(handleMoreDetailsClick(summary)).rejects.toThrow();
	});

	it('throws for an invalid click target with no usable imdbID attribute', async () => {
		const summary = { attributes: [], classList: { contains: vi.fn(() => false) } };

		await expect(handleMoreDetailsClick(summary)).rejects.toThrow();
	});
});

describe('handleLessDetailsClick', () => {
	it('collapses an open details section back to closed for a normal click', async () => {
		const summaryEl = { style: {} };
		const details = {
			removeAttribute: vi.fn(),
			querySelector: vi.fn(() => summaryEl),
		};
		const eTarget = { closest: vi.fn(() => details) };

		await handleLessDetailsClick(eTarget);

		expect(details.removeAttribute).toHaveBeenCalledWith('open');
		expect(summaryEl.style.display).toBe('unset');
	});

	it('does nothing when the click target has no enclosing <details> element', async () => {
		const eTarget = { closest: vi.fn(() => null) };

		await expect(handleLessDetailsClick(eTarget)).resolves.toBeUndefined();
	});

	it('throws for an invalid target that has no closest() method', async () => {
		const eTarget = {};

		await expect(handleLessDetailsClick(eTarget)).rejects.toThrow();
	});
});

